import os, sys

for root, dirs, files in os.walk(os.getcwd()):
    # skip hidden dirs like .codex to keep output small
    dirs[:] = [d for d in dirs if not d.startswith('.')]
    depth = root.replace(os.getcwd(), '').count(os.sep)
    if depth > 4:
        continue
    for f in files:
        p = os.path.join(root, f)
        print(p)
